/// A level at a moment, for [`Op::Volume`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct VolumeKey {
    /// Timeline seconds.
    pub at: f64,
    /// Decibels: 0 is full level.
    pub db: f32,
}

/// A track control's value at a moment, for [`Op::TrackAutomation`]:
/// `db` for its volume, `pan` for its pan.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AutomationKey {
    /// Sequence seconds.
    pub at: f64,
    /// The track's level in dB, 0 at unity; -60 and below is silence.
    #[serde(default)]
    pub db: Option<f32>,
    /// -1 left to 1 right.
    #[serde(default)]
    pub pan: Option<f32>,
}

/// A point on the timeline, said the way an editor says it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Anchor {
    /// Seconds from the start of the timeline.
    Secs(f64),
    /// A frame number at the sequence's rate.
    Frame(i64),
    /// Where a clip starts: the clip by id, or by where it is, which is
    /// how a step names a clip an earlier step of the same plan placed.
    ClipStart(ClipRef),
    /// Where a clip ends.
    ClipEnd(ClipRef),
    /// Where the last clip on a track ends (the start, on an empty
    /// track): where the next select of an assembly goes.
    TrackEnd(TrackRef),
    /// A timeline marker, by its label (case-insensitive).
    Marker(String),
    /// Another anchor moved by some seconds, negative for earlier.
    Offset { from: Box<Anchor>, secs: f64 },
}

/// A clip, by its id or by where it is: the clip covering `secs` on
/// track `track`, as the document stands when the op runs. The latter
/// is how a step names the halves a split before it made. Or `"@N"`: the
/// clip step N of the same apply made or changed, its first (#790), so a
/// place and the role, level and effects of what it placed are one apply.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ClipRef {
    Id(ClipId),
    At { track: usize, secs: f64 },
    Made(StepRef),
}

/// `"@N"`: step N of the same apply, counted from 0.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StepRef(pub usize);

impl Serialize for StepRef {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&format!("@{}", self.0))
    }
}

impl<'de> Deserialize<'de> for StepRef {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = String::deserialize(d)?;
        s.strip_prefix('@')
            .and_then(|n| n.parse().ok())
            .map(StepRef)
            .ok_or_else(|| serde::de::Error::custom(format!("{s:?} is not a clip id, {{track, secs}} or \"@N\" (the clip step N of this apply made)")))
    }
}

/// The fields that name a clip (#809 review): only their `"@N"` is a
/// step reference. A name, a role or a group spelled "@0" is left as
/// written; a clip field missed here fails safe, as "@N was not bound".
const CLIP_REF_KEYS: &[&str] = &["clip_id", "clips", "from", "source", "incoming_clip", "outgoing_clip", "clip_start", "clip_end"];

/// The op with every `"@N"` in a field that names a clip replaced by the
/// id of the clip step N made (`made[N]`), read through the op's own
/// JSON so every such field is covered.
fn bind_step_refs(op: &Op, i: usize, made: &[Option<ClipId>]) -> Result<Op, Refusal> {
    fn walk(v: &mut serde_json::Value, key: Option<&str>, i: usize, made: &[Option<ClipId>]) -> Result<(), Refusal> {
        match v {
            serde_json::Value::String(s) if key.is_some_and(|k| CLIP_REF_KEYS.contains(&k)) => {
                if let Some(n) = s.strip_prefix('@').and_then(|n| n.parse::<usize>().ok()) {
                    let id = match made.get(n) {
                        Some(Some(id)) => *id,
                        Some(None) => return Err(refuse(i, format!("@{n} names step {n}, which made or changed no clip"), "name a step that places, titles or edits a clip")),
                        None => return Err(refuse(i, format!("@{n} names step {n}, which comes at or after this one"), "a step can only name a clip an earlier step made")),
                    };
                    *s = id.0.to_string();
                }
            }
            serde_json::Value::Array(a) => {
                for x in a {
                    walk(x, key, i, made)?;
                }
            }
            serde_json::Value::Object(o) => {
                for (k, x) in o.iter_mut() {
                    walk(x, Some(k.as_str()), i, made)?;
                }
            }
            _ => {}
        }
        Ok(())
    }
    let mut v = serde_json::to_value(op).map_err(|e| refuse(i, format!("the op could not be read back: {e}"), "name clips by id"))?;
    if !v.to_string().contains("\"@") {
        return Ok(op.clone());
    }
    let as_given = v.clone();
    walk(&mut v, None, i, made)?;
    // Nothing bound (an "@" in a text, a handle like "@harbourfilms"):
    // the op as it came, with what it carries but never sends.
    if v == as_given {
        return Ok(op.clone());
    }
    let mut bound: Op = serde_json::from_value(v).map_err(|e| refuse(i, format!("the op could not be read back: {e}"), "name clips by id"))?;
    // A template's file is read by whoever resolves the op and is never
    // sent: read back without it, the template was "not there" (#2733).
    if let (Op::Template { data: kept, composition: kept_composition, .. }, Op::Template { data, composition, .. }) = (op, &mut bound) {
        *data = kept.clone();
        *composition = kept_composition.clone();
    }
    Ok(bound)
}

/// Which neighbour a [`Op::Join`] closes the edit with.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum JoinSide {
    #[default]
    Next,
    Previous,
}

/// Where a `look` or a `grade` goes, when not on one clip (#237): the
/// timeline grade, over every clip after its own ("timeline"), or a grade
/// group's post-clip grade, after each member's own, or its pre-clip
/// grade, before it (`{"group": name, "stage": "pre"}`). With
/// `{"track": index or kind}` it goes on every clip of that track that
/// can take it, between `from` and `to` when given, as one step (#847);
/// with `"itself": true`, on the track itself (#846).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum GradeOn {
    Group {
        group: String,
        #[serde(default)]
        stage: Option<klipp_timeline::GradeStage>,
    },
    Track {
        track: TrackRef,
        #[serde(default)]
        from: Option<Anchor>,
        #[serde(default)]
        to: Option<Anchor>,
        /// On the track itself rather than on each of its clips (#846):
        /// one effect or grade the track runs after every clip's own,
        /// clips added later included.
        #[serde(default)]
        itself: bool,
    },
    Named(String),
}

/// Which track a clip goes on.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum TrackRef {
    /// A track's index in the sequence, top first, as the views list them.
    Index(usize),
    /// The first track of a kind: "video", "audio", "text".
    Kind(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Edge {
    In,
    Out,
}

/// How a title's text is set, for `title` and `style` (#1686): its
/// weight, a variable font's axes, OpenType features, a justified
/// paragraph's last line, its place up and down its box, an underline,
/// and styled runs of it.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Typeset {
    /// 100 (thin) to 900 (black).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub weight: Option<u16>,
    /// A variable font's axes by four-letter tag, in the axis's units:
    /// `{"wdth": 80, "opsz": 36}`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub axes: Option<std::collections::BTreeMap<String, f32>>,
    /// OpenType features: "smcp" on, "-liga" off, "ss01=1" a value.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub features: Option<Vec<String>>,
    /// A justified paragraph's last line: left, center or justify.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_line: Option<String>,
    /// The text's place up and down its box: top, middle or bottom.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub valign: Option<String>,
    /// How a text too long for its box meets it (#1722): "wrap" (between
    /// words, smaller until it is no taller than the box), "shrink" (on
    /// its typed lines, smaller until they fit, not below `min_size`) or
    /// "grow" (wrapped at its size, the box and a backing fitted to it
    /// growing with the lines).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fit: Option<String>,
    /// The smallest a shrinking text is set, in the units of `size`;
    /// 24 when not given.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min_size: Option<f32>,
    /// The box's paragraphs (#1721): the space between them and their
    /// indents, pixels at 1080p.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub paragraph: Option<ParagraphSpec>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub underline: Option<bool>,
    /// Styled stretches of the text, in place of any it had; `[]` clears
    /// them.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub runs: Option<Vec<RunSpec>>,
    /// Animators (#1701): presets by name or full, in place of any the
    /// text had; `[]` clears them.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub animators: Option<Vec<AnimatorSpec>>,
    /// Keys on the text's size, tracking, line spacing, colour and
    /// gradient stops, in seconds from the title's start (#1701).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub keys: Option<KeysSpec>,
    /// The text along a path layer of the same title, or `"none"` (#1701).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub on_path: Option<OnPathSpec>,
    /// How the text layer mixes with the layers below it (#1513).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub blend: Option<String>,
    /// Another layer of the same title masking the text, or `"none"`
    /// (#1513).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mask: Option<MaskSpec>,
    /// The text in 3D (#1512): a look and settings, or `"none"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub three_d: Option<ThreeDSpec>,
    /// A metal face (#2706): a preset by name ("gold"), its fields over
    /// a preset, or `"none"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub material: Option<MaterialSpec>,
    /// Keeps the text readable over the picture (#2734): "auto" darkens
    /// or lightens the picture round the text only as far as it needs,
    /// "always" lays that halo whatever is behind, "off" leaves the
    /// picture. The whole title takes it; a new title is "auto".
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub protect: Option<klipp_timeline::ContrastProtect>,
}
/// "A name or an object" specs read so that an object's own error (an
/// unknown field, a value of the wrong kind) is the reply's, not "did
/// not match any variant": a string is the name form, anything else the
/// object form, read as it is.
macro_rules! name_or_fields {
    ($ty:ident, $off:ident, $on:ident, $fields:ty) => {
        impl<'de> Deserialize<'de> for $ty {
            fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
                match serde_json::Value::deserialize(d)? {
                    serde_json::Value::String(s) => Ok($ty::$off(s)),
                    v => serde_json::from_value::<$fields>(v).map(|f| $ty::$on(f.into())).map_err(serde::de::Error::custom),
                }
            }
        }
    };
}

name_or_fields!(ThreeDSpec, Off, On, ThreeD);
name_or_fields!(BevelSpec, Off, On, BevelOn);
name_or_fields!(MaskSpec, Off, Layer, MaskLayer);
name_or_fields!(OnPathSpec, Off, Path, PathSpec);
name_or_fields!(MaterialSpec, Named, On, MaterialFields);
name_or_fields!(RimSpec, Off, On, MetalLightSpec);

/// A metal face (#2706) as an op gives it: a preset's name (gold,
/// silver, steel or iron, copper, bronze, chrome, brushed_metal) or
/// `"none"`, or fields over a preset (`preset` named) or over the text's
/// metal as it is.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(untagged)]
pub enum MaterialSpec {
    Named(String),
    On(Box<MaterialFields>),
}

/// The fields of a [`MaterialSpec`]: amounts 0..1 unless said, colours
/// #rrggbb.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MaterialFields {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub preset: Option<String>,
    /// The metal's colour.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tint: Option<String>,
    /// 0 a mirror, 1 satin.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub roughness: Option<f32>,
    /// Brushed streaks, along `anisotropy_angle` degrees.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub anisotropy: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub anisotropy_angle: Option<f32>,
    /// The fresnel edge.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<f32>,
    /// The lights' highlights, 0..2.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub highlights: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub glints: Option<f32>,
    /// The bevel's width as a fraction of the text's size (0..0.3), and
    /// its steepness.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bevel: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub depth: Option<f32>,
    /// A dark line round the letters' outer edge.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub contour: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub environment: Option<EnvironmentSpec>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub key_light: Option<MetalLightSpec>,
    /// A second light from behind the edges, or `"none"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rim_light: Option<RimSpec>,
}

/// What the metal reflects, as strengths 0..2: a studio, a sky (tinted)
/// and the shot behind the title, blurred by `shot_blur` (a fraction of
/// the frame's height, up to 0.2).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct EnvironmentSpec {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub studio: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sky: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub shot: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub shot_blur: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sky_tint: Option<String>,
}

/// A light on the metal: azimuth degrees around (0 from the right, 90
