pub use klipp_timeline::ShadowSpec;

/// A title's `gradient`: `["#top", "#bottom"]`, as it always was, or
/// any number of stops (#1509), `{"stops": [[0, "#rrggbb"], [0.5, ...],
/// [1, ...]]}`, along `angle` (degrees: 0 top to bottom, the default, 90
/// left to right) or out from a centre, `"radial": {"x", "y", "r"}` in
/// fractions of the text block.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum GradientSpec {
    Pair([String; 2]),
    Stops(GradientStops),
}

/// The stops form of a [`GradientSpec`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GradientStops {
    /// `[position 0..1, "#rrggbb"]`, two to sixteen.
    pub stops: Vec<(f32, String)>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub angle: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub radial: Option<RadialSpec>,
}

/// A radial gradient's centre and radius, in fractions of the box.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RadialSpec {
    pub x: f32,
    pub y: f32,
    pub r: f32,
}

/// The gradient a spec asks for (#1509), or why it can't be.
fn title_gradient(spec: &GradientSpec, i: usize) -> Result<klipp_timeline::TextGradient, Refusal> {
    let colour = |c: &str| parse_color(c).ok_or_else(|| refuse(i, format!("\"{c}\" is not a colour"), "write the gradient colours as #rrggbb"));
    let g = match spec {
        GradientSpec::Pair([top, bottom]) => return Ok(klipp_timeline::TextGradient::pair(colour(top)?, colour(bottom)?, true)),
        GradientSpec::Stops(g) => g,
    };
    if !(2..=klipp_timeline::MAX_GRADIENT_STOPS).contains(&g.stops.len()) {
        return Err(refuse(i, format!("a gradient of {} stops", g.stops.len()), format!("give a gradient 2 to {} stops", klipp_timeline::MAX_GRADIENT_STOPS)));
    }
    let mut stops = Vec::with_capacity(g.stops.len());
    for (position, c) in &g.stops {
        if !position.is_finite() || !(0.0..=1.0).contains(position) {
            return Err(refuse(i, format!("gradient stop at {position} is out of range"), "give each stop a position 0 to 1"));
        }
        stops.push(klipp_timeline::GradientStop { position: *position, color: colour(c)? });
    }
    let kind = match (g.angle, g.radial) {
        (Some(_), Some(_)) => return Err(refuse(i, "a gradient both at an angle and radial", "give either angle or radial")),
        (_, Some(RadialSpec { x, y, r })) => {
            if ![x, y, r].iter().all(|v| v.is_finite()) || !(-1.0..=2.0).contains(&x) || !(-1.0..=2.0).contains(&y) || !(0.01..=2.0).contains(&r) {
                return Err(refuse(i, format!("radial gradient at ({x}, {y}) of radius {r} is out of range"), "give the centre x and y -1 to 2 and the radius r 0.01 to 2, as fractions of the text"));
            }
            klipp_timeline::GradientKind::Radial { centre: [x, y], radius: r }
        }
        (angle, None) => match angle.unwrap_or(0.0) {
            a if a.is_finite() && (-360.0..=360.0).contains(&a) => klipp_timeline::GradientKind::Linear { angle_deg: a },
            a => return Err(refuse(i, format!("gradient angle {a} is out of range"), "give the angle -360 to 360 degrees")),
        },
    };
    Ok(klipp_timeline::TextGradient::with_stops(&stops, kind, true))
}

/// The shadow a spec asks for, or `None` at opacity 0.
fn title_shadow(spec: &ShadowSpec, i: usize) -> Result<Option<klipp_timeline::TitleShadow>, Refusal> {
    let range = |v: Option<f32>, default: f32, lo: f32, hi: f32, what: &str| match v {
        Some(v) if !v.is_finite() || !(lo..=hi).contains(&v) => Err(refuse(i, format!("shadow {what} {v} is out of range"), format!("give the shadow's {what} {lo} to {hi}"))),
        v => Ok(v.unwrap_or(default)),
    };
    let x = range(spec.x, 0.0, -100.0, 100.0, "x")?;
    let y = range(spec.y, 4.0, -100.0, 100.0, "y")?;
    let blur = range(spec.blur, 8.0, 0.0, 100.0, "blur")?;
    let opacity = range(spec.opacity, 0.6, 0.0, 1.0, "opacity")?;
    let mut color = match spec.color.as_deref() {
        Some(c) => parse_color(c).ok_or_else(|| refuse(i, format!("\"{c}\" is not a colour"), "write the shadow colour as #rrggbb"))?,
        None => [0, 0, 0, 255],
    };
    if opacity <= 0.0 {
        return Ok(None);
    }
    color[3] = (color[3] as f32 * opacity).round() as u8;
    Ok(Some(klipp_timeline::TitleShadow {
        enabled: true,
        color,
        offset_x: x,
        offset_x_keyframes: Vec::new(),
        offset_y: y,
        offset_y_keyframes: Vec::new(),
        blur,
        blur_keyframes: Vec::new(),
    }))
}

/// A type style's shadow as a title takes it, or why its values can't
/// be: what `set_brief` holds a style's shadow to.
pub fn type_style_shadow(spec: &ShadowSpec) -> Result<Option<klipp_timeline::TitleShadow>, String> {
    title_shadow(spec, 0).map_err(|r| format!("shadow: {}. {}", r.why, r.hint))
}

/// What a `style` op changes, gathered.
#[derive(Debug, Clone, Default, PartialEq)]
struct Look {
    full_frame: Option<[u8; 4]>,
    size: Option<f32>,
    color: Option<[u8; 4]>,
    font: Option<String>,
    bold: Option<bool>,
    align: Option<klipp_timeline::TextAlignment>,
    x: Option<f32>,
    y: Option<f32>,
    backing: Option<f32>,
    outline: Option<f32>,
    /// `Some(None)` takes the shadow off.
    shadow: Option<Option<klipp_timeline::TitleShadow>>,
    backing_color: Option<[u8; 4]>,
    outline_color: Option<[u8; 4]>,
    glow: Option<f32>,
    glow_color: Option<[u8; 4]>,
    gradient: Option<klipp_timeline::TextGradient>,
    glitch: Option<f32>,
    chromatic: Option<f32>,
    /// The motion asked for, fitted to each title's length when applied.
    motion: Option<MotionAsk>,
    /// A loop by name, "none" taking any loop off.
    loop_effect: Option<String>,
    roll_shape: Option<klipp_core::title_motion::RollShape>,
    edge_fade: Option<klipp_core::title_motion::EdgeFade>,
    /// Weight, axes, features, last line, vertical place, underline and
    /// runs (#1686).
    typeset: Typesetting,
}

/// A `style` op's motion fields, as `title` takes them.
#[derive(Debug, Clone, Default, PartialEq)]
struct MotionAsk {
    enter: Option<klipp_timeline::TitleMotionSpec>,
    exit: Option<klipp_timeline::TitleMotionSpec>,
    animate: Option<String>,
    animate_secs: Option<f32>,
    stagger: Option<String>,
}

impl MotionAsk {
    /// The motion for a title `secs` long.
    fn fit(&self, secs: f64) -> Result<klipp_core::title_motion::TitleMotion, String> {
        crate::title_style::effective_motion(
            &klipp_timeline::TypeStyle::default(),
            self.enter.as_ref(),
            self.exit.as_ref(),
            self.animate.as_deref(),
            self.animate_secs.map(f64::from),
            self.stagger.as_deref(),
            secs,
        )
    }
}

/// A title loop by name: its colours from the text and its glow, a roll
/// or crawl shaped by `shape`. `Ok(None)` for "none" or "off".
fn title_loop(
    name: &str,
    color: [u8; 4],
    glow: Option<[u8; 4]>,
    shape: Option<klipp_core::title_motion::RollShape>,
    i: usize,
) -> Result<Option<klipp_core::title_motion::TitleLoop>, Refusal> {
    use klipp_core::title_motion::TitleLoop;
    Ok(Some(match name.to_lowercase().as_str() {
        "none" | "off" => return Ok(None),
        "pulse" | "breathe" => TitleLoop::Pulse { rate_hz: 1.0, min_opacity: 0.4 },
        "flash" | "blink" => TitleLoop::Blink { rate_hz: 2.0, duty: 0.6 },
        "neon" => TitleLoop::ColorBlend { color_a: color, color_b: glow.unwrap_or([255, 40, 120, 255]), rate_hz: 1.5 },
        "wave" => TitleLoop::Wave { amplitude: 0.12, rate_hz: 1.0 },
        "shake" => TitleLoop::Shake { amplitude: 0.04, rate_hz: 10.0 },
        "color_cycle" | "colour_cycle" | "rainbow" => TitleLoop::ColorCycle { rate_hz: 0.4 },
        // A credits roll and a ticker, fitted to the title's length
        // (#588): the speed is set in the Title tab.
        "scroll" | "roll" | "credits" => TitleLoop::Scroll { direction: klipp_timeline::ScrollDirection::Up, speed_px_per_sec: 0.0, shape: shape.unwrap_or_default() },
        "float" | "bob" => TitleLoop::Float { amplitude: 0.08, rate_hz: 0.5 },
        "sway" => TitleLoop::Sway { amplitude: 0.1, rate_hz: 0.4 },
        "neon_flicker" | "flicker_loop" => TitleLoop::Flicker { rate_hz: 6.0, depth: 0.25 },
        "drift" => TitleLoop::Drift { dx: -0.04, dy: 0.0 },
        "crawl" | "ticker" => TitleLoop::Crawl { direction: klipp_timeline::CrawlDirection::Left, speed_px_per_sec: 0.0, repeat: false, shape: shape.unwrap_or_default() },
        other => return Err(refuse(i, format!("\"{other}\" is not a loop"), "use pulse, flash, neon, wave, shake, color_cycle, float, sway, neon_flicker, drift, scroll (a credits roll), crawl (a ticker), or none")),
    }))
}

