/// One pose of the camera: at `secs` on the timeline, looking at the
/// frame point `x`,`y`, `zoom` far in and rolled `roll_deg` clockwise.
/// It reads as a camera, so moving it right moves the scene left.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct CameraKey {
    #[serde(default)]
    pub secs: f64,
    #[serde(default = "half")]
    pub x: f32,
    #[serde(default = "half")]
    pub y: f32,
    #[serde(default = "one")]
    pub zoom: f32,
    #[serde(default)]
    pub roll_deg: f32,
    /// How the move into this key eases; `in_out` when left out.
    #[serde(default = "in_out")]
    pub ease: klipp_core::keyframe::Ease,
}

impl Default for CameraKey {
    fn default() -> Self {
        Self { secs: 0.0, x: 0.5, y: 0.5, zoom: 1.0, roll_deg: 0.0, ease: klipp_core::keyframe::Ease::InOut }
    }
}

/// One pose of a composed picture: at `secs` into the clip, its centre
/// on the frame point `x`,`y` covering `width` by `height` of the frame,
/// turned `rotation_deg` clockwise about that centre and `opacity` seen.
/// All of it is fractions of the frame, so the same pose means the same
/// thing whatever the delivery size. `x` and `y` reach past the frame so
/// a picture can start off screen and move in.
///
/// A clip's ends sit on frames, so its length can differ from the one
/// asked for by up to a frame: at 30 fps a clip placed from 28.15 s to
/// 37.70 s starts on 28.167 s and is 9.533 s long. A step's report gives
/// the clip's times as placed (`after`). A pose up to one frame past the
/// end is taken as the end; `from_end_secs` names a time from the end
/// whatever the snapping did (#1925).
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct ComposePose {
    /// Seconds into the clip, 0 to its length once its ends are on frames.
    #[serde(default)]
    pub secs: f64,
    /// Seconds before the clip's end, in place of `secs`: 0 is its end.
    /// Measured from where the end landed on a frame, so a closing pose
    /// needs no arithmetic on the length asked for (#1925).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub from_end_secs: Option<f64>,
    /// Where the picture's centre goes, fractions of the frame. Left
    /// out, with `width` and `height`, the pose keeps where the clip is
    /// and how large, as reframed or composed before (#728): an opacity
    /// ramp needs no geometry.
    #[serde(default)]
    pub x: Option<f32>,
    #[serde(default)]
    pub y: Option<f32>,
    #[serde(default)]
    pub width: Option<f32>,
    #[serde(default)]
    pub height: Option<f32>,
    /// Left out, 0, or in a pose with no geometry the clip's own turn.
    #[serde(default)]
    pub rotation_deg: Option<f32>,
    #[serde(default = "one")]
    pub opacity: f32,
    /// How the move into this pose eases; `in_out` when left out.
    #[serde(default = "in_out")]
    pub ease: klipp_core::keyframe::Ease,
    /// Tilt in perspective about the picture's horizontal axis, degrees:
    /// positive leans the top away, like a screen on a desk.
    #[serde(default)]
    pub tilt_x_deg: Option<f32>,
    /// Tilt in perspective about its vertical axis, degrees: positive
    /// swings the right edge away, like a door.
    #[serde(default)]
    pub tilt_y_deg: Option<f32>,
}

impl Default for ComposePose {
    fn default() -> Self {
        Self { secs: 0.0, from_end_secs: None, x: None, y: None, width: None, height: None, rotation_deg: None, opacity: 1.0, ease: klipp_core::keyframe::Ease::InOut, tilt_x_deg: None, tilt_y_deg: None }
    }
}

fn in_out() -> klipp_core::keyframe::Ease {
    klipp_core::keyframe::Ease::InOut
}

/// Ease each move into a key: `eases[k]` shapes the move from key `k - 1`
/// into key `k`, on every track, all written at the same times. A track
/// with a different count — two keys closer than a keyframe allows — is
/// left linear rather than eased against the wrong neighbours.
fn ease_tracks(tracks: &mut [&mut Vec<klipp_core::Keyframe>], eases: &[klipp_core::keyframe::Ease]) {
    for t in tracks.iter_mut().filter(|t| t.len() == eases.len()) {
        for (k, e) in eases.iter().enumerate().skip(1) {
            klipp_core::keyframe::ease_into(t, k, *e);
        }
    }
}

fn one() -> f32 {
    1.0
}

/// One pose of a pan: at `secs` into the clip, `scale` centred on the
/// frame point `x`,`y` (fractions of the frame).
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct PanKey {
    pub secs: f64,
    #[serde(default = "default_reframe_scale")]
    pub scale: f32,
    #[serde(default = "half")]
    pub x: f32,
    #[serde(default = "half")]
    pub y: f32,
    /// How the move into this pose eases; `in_out` when left out.
    #[serde(default = "in_out")]
    pub ease: klipp_core::keyframe::Ease,
}

fn half() -> f32 {
    0.5
}

/// The poses a follow makes of the spots: to each spot, a hold, and back
/// out unless the next is near.
pub fn follow_keys(spots: &[(f64, f32, f32)], clip_secs: f64, scale: f32, hold: f64) -> Vec<PanKey> {
    const EASE: f64 = 0.35;
    let rest = |t: f64| PanKey { secs: t, scale: 1.0, x: 0.5, y: 0.5, ease: klipp_core::keyframe::Ease::InOut };
    let mut keys: Vec<PanKey> = Vec::new();
    let mut last_end: Option<f64> = None;
    for (n, (t, x, y)) in spots.iter().enumerate() {
        let start = (t - EASE).max(0.0);
        match last_end {
            // The next spot comes before the last hold is over: the hold
            // ends where the move to the next begins, no pull-out between.
            Some(e) if start <= e + EASE + 0.05 => {
                if let Some(end_key) = keys.pop() {
                    let prev_t = keys.last().map(|k| k.secs).unwrap_or(0.0);
                    let cut = start.max(prev_t);
                    if cut > prev_t + 1e-6 {
                        keys.push(PanKey { secs: cut, ..end_key });
                    }
                }
            }
            Some(e) => {
                keys.push(rest(e + EASE));
                keys.push(rest(start));
            }
            None => {
                if start > 0.0 {
                    keys.push(rest(0.0));
                    keys.push(rest(start));
                }
            }
        }
        let end = (t + hold).min(clip_secs);
        keys.push(PanKey { secs: *t, scale, x: *x, y: *y, ease: klipp_core::keyframe::Ease::InOut });
        keys.push(PanKey { secs: end, scale, x: *x, y: *y, ease: klipp_core::keyframe::Ease::InOut });
        last_end = Some(end);
        if n + 1 == spots.len() && end + EASE < clip_secs {
            keys.push(rest(end + EASE));
        }
    }
    keys.dedup_by(|a, b| (a.secs - b.secs).abs() < 1e-6);
    keys
}

fn default_reframe_scale() -> f32 {
    1.0
}

